"""Assign PENDING ledger rows to slices. Usage: slices.py <repo> <outdir>"""
import re, sys, os, fnmatch, collections, json
repo, out = sys.argv[1:3]
rows = [l for l in open(os.path.join(repo, "audit/LEDGER.md")) if re.match(r"\| \d+ \| `", l)]
pending = [re.search(r"`([^`]+)`", l).group(1) for l in rows if l.rstrip().endswith("| PENDING |")]
