assign = {}; per = collections.defaultdict(list)
for p in pending:
    for sid, name, pats in S:
        if any(fnmatch.fnmatchcase(p, pat) and (pat != "spectre/web/templates/*" or p.count("/") == 3) for pat in pats):
            assign[p] = sid; per[sid].append(p); break
assert len(assign) == len(pending), set(pending) - set(assign)
for sid, name, _ in S:
    open(os.path.join(out, sid + ".files"), "w").write("\n".join(per[sid]) + "\n")
    print(sid, len(per[sid]), name)
print("pending", len(pending), "assigned", len(assign), "unique", len(set(assign)))
